		/** 
		 * Tests creating a new Contact.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Contact");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Contact" );

			try {            
				Contact entity = ContactService.getContactInstance().createContact( generateNewEntity() );
				thePrimaryKey = entity.getContactId();
				LOGGER.info( "-- Successfully created a Contact with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Contact. 
		 */
		public Contact testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Contact" );

			Contact entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Contact with primary key" );
			msg.append( thePrimaryKey );
			
			ContactFetchOneSummary fetchOneSummary = new ContactFetchOneSummary( thePrimaryKey );

			try {
				entity = ContactService.getContactInstance().getContact( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Contact " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Contact.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Contact." );

			StringBuilder msg = new StringBuilder( "Failed to update a Contact : " );        
			Contact entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Contact." );

				// for use later on...
				thePrimaryKey = entity.getContactId();

				ContactService proxy = ContactService.getContactInstance();            
				proxy.updateContact( entity );   

				LOGGER.info( "-- Successfully saved Contact - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Contact.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Contact." );

			try{
			    Contact entity = testRead(); 
				ContactService.getContactInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Contact with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Contact with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Contacts.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Contacts:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Contact : " );        
			List<Contact> collection  = null;

			try {
				// call the static get method on the ContactService
				collection = ContactService.getContactInstance().getAllContact();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Contact entity = null;            
					Iterator<Contact> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getContactId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

